{
  "implementation": "def solve(case):
    payload = case['payload']
    segments = payload['segments']
    budget = payload['budget']

    sum_minima = 0
    sum_capacities = 0
    for s in segments:
        sum_minima += s['minimum']
        sum_capacities += s['capacity']

    if budget < sum_minima:
        raise ValueError('Budget below total minimum')
    if budget > sum_capacities:
        raise ValueError('Budget above total capacity')

    alloc = {}
    for s in segments:
        alloc[s['name']] = s['minimum']

    remaining = budget - sum_minima
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            if alloc[name] >= s['capacity']:
                continue
            next_pos = alloc[name] + 1
            score = s['importance'] / next_pos
            if score > best_score or (score == best_score and (best_idx == -1 or i < best_idx)):
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        name = segments[best_idx]['name']
        alloc[name] += 1
        remaining -= 1

    name_mapping = [s['name'] for s in segments]
    return {
        'allocations': alloc,
        'name_mapping': name_mapping,
        'total': budget
    }"
}
